<template>
  <view class="workspace"><aside class="rail"><view class="rail-brand"><view class="mark">安</view><view><view class="company">徐州中燃能源有限公司</view><view class="brand">徐燃安巡</view></view></view><view class="nav"><view class="nav-item active">待办工作台</view><view class="nav-item" @click="openMessages">消息中心 <text v-if="unread" class="nav-count">{{unread}}</text></view><view class="nav-item" @click="openOrders">整改单</view><view class="nav-item" @click="openDuty">我的履职</view><view v-if="demoStore.can('admin')" class="nav-item" @click="openAdmin">管理总览</view></view><view class="rail-footer">当前角色<br/><text>{{roleNames[demoStore.role]}}</text></view></aside>
    <main class="content"><view class="topbar"><view class="mobile-brand"><view class="mark">安</view><view><view class="company">徐州中燃能源有限公司</view><view class="brand">徐燃安巡</view></view></view><view class="top-actions"><view class="message-button" @click="openMessages">消息 <text v-if="unread">{{unread}}</text></view><view class="role">{{roleNames[demoStore.role]}}</view></view></view>
      <view class="hero"><view><view class="hero-label">今日需要处置</view><view class="hero-number">{{pendingCount}}</view><view class="hero-copy">所有处置过程留痕。闭环后不可删除或覆盖。</view></view><view class="hero-side"><view class="hero-date">{{today}}</view><view class="hero-status">安全闭环运行中</view></view></view>
      <view class="metric-grid"><view class="metric danger"><text>{{majorCount}}</text><span>重大隐患</span></view><view class="metric"><text>{{overdueCount}}</text><span>已逾期</span></view><view class="metric"><text>{{reviewCount}}</text><span>待安监复核</span></view><view class="metric"><text>{{closedCount}}</text><span>本期已闭环</span></view></view>
      <view class="section-head"><view><view class="section-title">闭环待办</view><view class="caption">按风险等级和整改期限排序</view></view><view class="section-actions"><button v-if="demoStore.can('issue-list')" class="minor" @click="openOrders">整改单</button><button v-if="demoStore.can('issue-create')" class="primary" @click="createIssue">随手拍上报</button></view></view>
      <view class="cards"><view v-for="issue in visibleIssues" :key="issue.id" class="issue" :class="{major:issue.major}" @click="openIssue(issue.id)"><view class="issue-top"><view class="status" :class="statusClass(issue.status)">{{issue.status}}</view><view v-if="issue.major" class="major-tag">重大隐患</view><view class="issue-id">{{issue.id}}</view></view><view class="issue-title">{{issue.title}}</view><view class="issue-meta"><text>{{issue.assignee || '等待安监交办'}}</text><text>期限 {{issue.deadline}}</text></view><view class="issue-bottom"><text>{{issue.location}}</text><text>查看详情 ›</text></view></view></view>
      <view v-if="!visibleIssues.length" class="empty"><view class="empty-title">当前没有待处理事项</view><view>新的隐患上报和系统提醒会显示在这里。</view></view>
    </main>
  </view>
</template>
<script setup>
import {computed} from 'vue'
import {demoStore,roleNames} from '../../stores/demo'
const visibleIssues=computed(()=>demoStore.visibleIssues()),pendingCount=computed(()=>visibleIssues.value.filter(x=>x.status!=='已闭环').length),majorCount=computed(()=>demoStore.issues.filter(x=>x.major&&x.status!=='已闭环').length),overdueCount=computed(()=>demoStore.issues.filter(x=>x.status==='已逾期').length),reviewCount=computed(()=>demoStore.issues.filter(x=>x.status==='待复核').length),closedCount=computed(()=>demoStore.issues.filter(x=>x.status==='已闭环').length),unread=computed(()=>demoStore.messages.filter(x=>!x.read).length),today=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'})
function statusClass(s){return ({'待交办':'draft','待整改':'todo','待复核':'review','已逾期':'overdue','已闭环':'closed'})[s]}function openIssue(id){uni.navigateTo({url:`/pages/issue/detail?id=${id}`})}function openMessages(){uni.navigateTo({url:'/pages/messages/index'})}function openOrders(){uni.navigateTo({url:'/pages/issue/list'})}function openDuty(){uni.switchTab({url:'/pages/duty/index'})}function openAdmin(){uni.navigateTo({url:'/pages/admin/duty'})}function createIssue(){uni.switchTab({url:'/pages/issue/create'})}
</script>
